CREATE TRIGGER `grammar_retention_follow_wording_published_content` AFTER UPDATE OF `status` ON `content_versions` WHEN `OLD`.`status` NOT IN ('schema-validated', 'pilot-ready') AND `NEW`.`status` IN ('schema-validated', 'pilot-ready') AND `NEW`.`retention_reset` = 0 AND NOT EXISTS (SELECT 1 FROM content_versions v WHERE v.skill_id = NEW.skill_id AND v.language = NEW.language AND v.status IN ('schema-validated', 'pilot-ready') AND v.version > NEW.version) BEGIN UPDATE `grammar_retention_schedules` SET `content_version_id` = `NEW`.`id`, `revision` = `revision` + 1 WHERE `skill_id` = `NEW`.`skill_id` AND `language` = `NEW`.`language` AND `content_version_id` <> `NEW`.`id`; END;
